/* Generado por scripts/build-mission-goals.cjs desde research/guides/bloques/*.json: bloques de cada misión en orden
   cronológico (objetivo de maestría o explicación propia). No editar a mano. */
(function(root){const byMission={"RED-15":[{"goal":"pokedex"},{"key":"magikarp-del-vendedor-del-monte-moon","title":"Magikarp del vendedor del Monte Moon","text":"Cuándo: antes de cruzar el Monte Moon, con 500 ₽ en el bolsillo. Dónde: Centro Pokémon de la Ruta 4, al pie del Monte Moon (llegas desde Ciudad Plateada por la Ruta 3). Paso a paso: 1) Entra en el Centro Pokémon que hay junto a la entrada del Monte Moon. 2) Habla con el hombre que vende un Magikarp de nivel 5 por 500 ₽ y responde que sí. 3) Si no llevas 500 ₽ no te lo vende; puedes volver más tarde, la oferta no caduca. 4) Súbelo al nivel 20 para que evolucione a Gyarados y registra las dos especies. Consejo: solo lo vende una vez y no admite devoluciones; si lo dejas pasar, la Caña Vieja (casa del pescador de Ciudad Carmín) solo pesca Magikarp. Fuente: decompilación de pret (pokered: scripts/MtMoonPokecenter, scripts/VermilionOldRodHouse); WikiDex («Monte Moon»)."},{"key":"fosil-del-monte-moon-kabuto-u-omanyte","title":"Fósil del Monte Moon: Kabuto u Omanyte","text":"Cuándo: al cruzar el Monte Moon; se revive al llegar a Isla Canela. Dónde: Monte Moon, último sótano (sótano 2), y la sala de fósiles del Laboratorio Pokémon de Isla Canela. Paso a paso: 1) En el último sótano del Monte Moon vence al Supernecio que custodia los dos fósiles. 2) Elige el Fósil Domo (Kabuto) o el Fósil Hélix (Omanyte): el otro ya no se puede coger en esta partida. 3) En Isla Canela entra en el Laboratorio Pokémon, ve a la sala de fósiles y dale el fósil al científico. 4) Sal del laboratorio a la calle, vuelve a entrar y háblale: te entrega Kabuto u Omanyte de nivel 30. 5) Súbelo al nivel 40 para registrar Kabutops u Omastar. Consejo: el científico solo revive un fósil a la vez; el que no elegiste tiene su propio bloque más abajo. Fuente: decompilación de pret (pokered: data/maps/objects/MtMoonB2F, scripts/CinnabarLabFossilRoom, scripts/CinnabarIsland); WikiDex («Monte Moon»)."},{"key":"intercambio-de-ciudad-celeste-poliwhirl-por-jynx","title":"Intercambio de Ciudad Celeste: Poliwhirl por Jynx","text":"Cuándo: cuando tengas un Poliwhirl; en la práctica, tras conseguir la Caña Buena en Ciudad Fucsia. Dónde: Ciudad Celeste, casa de intercambio. Paso a paso: 1) Pesca un Poliwag con la Caña Buena (te la regala el pescador de Ciudad Fucsia) y súbelo al nivel 25, o pesca un Poliwhirl con la Supercaña (casa de la Ruta 12). 2) Entra en la casa de intercambio de Ciudad Celeste y habla con quien busca un Poliwhirl. 3) Acepta y entrega a tu Poliwhirl: recibes una Jynx, que no aparece salvaje en el juego. Consejo: guarda otro Poliwhirl si también quieres registrar Poliwrath (Piedra Agua). Fuente: decompilación de pret (pokered: data/events/trades, scripts/CeruleanTradeHouse, data/wild/good_rod, scripts/FuchsiaGoodRodHouse); WikiDex («Ciudad Celeste»)."},{"key":"intercambio-de-la-via-subterranea-nidoran-por-nidoran","title":"Intercambio de la Vía Subterránea: Nidoran♂ por Nidoran♀","text":"Cuándo: en cuanto llegues a la Ruta 5, al sur de Ciudad Celeste. Dónde: Ruta 5: caseta de entrada de la Vía Subterránea. Paso a paso: 1) Captura un Nidoran♂ en la Ruta 22 (al oeste de Ciudad Verde) o en la Zona Safari. 2) Entra en la caseta de la Vía Subterránea de la Ruta 5 y habla con quien busca un Nidoran♂. 3) Acepta: recibes una Nidoran♀. Consejo: Nidoran♀ también sale salvaje en la Ruta 22, así que este intercambio solo te ahorra la captura. Fuente: decompilación de pret (pokered: data/events/trades, scripts/UndergroundPathRoute5, data/wild/maps/Route22); WikiDex («Vía Subterránea»)."},{"key":"intercambio-de-ciudad-carmin-spearow-por-farfetch-d","title":"Intercambio de Ciudad Carmín: Spearow por Farfetch'd","text":"Cuándo: al llegar a Ciudad Carmín. Dónde: Ciudad Carmín, casa de intercambio. Paso a paso: 1) Captura un Spearow (Rutas 3, 4, 9, 10, 11 o 22, entre otras). 2) Entra en la casa de intercambio de Ciudad Carmín y habla con quien busca un Spearow. 3) Acepta: recibes a Farfetch'd, que no aparece salvaje en esta edición. Consejo: es la única forma de registrar Farfetch'd sin intercambiar con otra consola. Fuente: decompilación de pret (pokered: data/events/trades, scripts/VermilionTradeHouse, data/wild/maps); WikiDex («Ciudad Carmín»)."},{"key":"intercambio-del-puesto-de-la-ruta-11-nidorino-por-nidorina","title":"Intercambio del puesto de la Ruta 11: Nidorino por Nidorina","text":"Cuándo: cuando tengas un Nidorino (Nidoran♂ evoluciona al nivel 16). Dónde: Ruta 11, al este de Ciudad Carmín: puesto de control, planta de arriba. Paso a paso: 1) Sube un Nidoran♂ al nivel 16 para tener un Nidorino. 2) Entra en el puesto de control de la Ruta 11 y sube a la planta de arriba. 3) Habla con quien busca un Nidorino y acepta: recibes una Nidorina. Consejo: Nidorina también se consigue evolucionando una Nidoran♀ (nv. 16) o en la Zona Safari; usa una Piedra Lunar para Nidoqueen. Fuente: decompilación de pret (pokered: data/events/trades, scripts/Route11Gate2F); WikiDex («Ruta 11»)."},{"key":"ayudante-de-oak-de-la-ruta-11-buscaobjetos-30-especies","title":"Ayudante de Oak de la Ruta 11: Buscaobjetos (30 especies)","text":"Cuándo: cuando tengas 30 especies registradas como capturadas. Dónde: Ruta 11, puesto de control, planta de arriba. Paso a paso: 1) Comprueba en la Pokédex que tienes al menos 30 especies capturadas. 2) Sube a la planta de arriba del puesto de la Ruta 11 y habla con el ayudante del profesor Oak. 3) Te entrega el Buscaobjetos, que pita cuando hay un objeto oculto cerca. Consejo: si aún no llegas a 30, el ayudante te dice cuántas te faltan; vuelve más tarde. Fuente: decompilación de pret (pokered: scripts/Route11Gate2F); WikiDex («Zahorí»)."},{"key":"intercambio-de-la-casa-de-la-ruta-2-abra-por-mr-mime","title":"Intercambio de la casa de la Ruta 2: Abra por Mr. Mime","text":"Cuándo: cuando tengas un Abra y acceso a la parte este de la Ruta 2. Dónde: Ruta 2, zona este: casa de intercambio (se llega cruzando la Cueva Diglett desde la Ruta 11 o usando Corte). Paso a paso: 1) Captura un Abra en las Rutas 24 o 25 (huye al primer turno: duérmelo o lanza la Poké Ball enseguida). 2) Cruza la Cueva Diglett desde la Ruta 11 (o corta el arbolito de la Ruta 2) y entra en la casa de intercambio. 3) Habla con quien busca un Abra y acepta: recibes a Mr. Mime, que no aparece salvaje. Consejo: guarda otro Abra para Kadabra y Alakazam. Fuente: decompilación de pret (pokered: data/events/trades, scripts/Route2TradeHouse, data/maps/objects/Route2); WikiDex («Ruta 2»)."},{"key":"ayudante-de-oak-de-la-ruta-2-mo05-destello-10-especies","title":"Ayudante de Oak de la Ruta 2: MO05 Destello (10 especies)","text":"Cuándo: cuando tengas 10 especies registradas como capturadas. Dónde: Ruta 2, zona este: puesto de control que corta el camino, al sur de la casa de intercambio. Paso a paso: 1) Comprueba en la Pokédex que tienes al menos 10 especies capturadas. 2) Llega a la zona este de la Ruta 2 por la Cueva Diglett (desde la Ruta 11) o con Corte y entra en el puesto de control. 3) Habla con el ayudante del profesor Oak: te da la MO05 (Destello), que ilumina el Túnel Roca (requiere la Medalla Roca). Consejo: conviene recogerla antes de cruzar el Túnel Roca. Fuente: decompilación de pret (pokered: scripts/Route2Gate, data/maps/objects/Route2); WikiDex («Ruta 2»)."},{"key":"ambar-viejo-aerodactyl","title":"Ámbar Viejo: Aerodactyl","text":"Cuándo: en cuanto puedas usar Corte fuera de combate (MO01 del capitán del S.S. Anne y Medalla Cascada); se revive en Isla Canela. Dónde: Ciudad Plateada, parte trasera del Museo de la Ciencia, y la sala de fósiles del Laboratorio Pokémon de Isla Canela. Paso a paso: 1) Vuelve a Ciudad Plateada y corta el arbolito que da paso a la entrada lateral del Museo de la Ciencia. 2) Entra por esa puerta: el científico de la sala te da el Ámbar Viejo. 3) En Isla Canela entrégalo al científico de la sala de fósiles del Laboratorio Pokémon (si está reviviendo tu otro fósil, recoge ese antes). 4) Sal a la calle, vuelve a entrar y recoge a Aerodactyl de nivel 30. Consejo: el Ámbar Viejo no caduca: puedes revivirlo cuando quieras. Fuente: decompilación de pret (pokered: scripts/Museum1F, scripts/CinnabarLabFossilRoom); WikiDex («Ámbar Viejo», «Museo de la Ciencia de Ciudad Plateada»)."},{"key":"eevee-de-la-azotea-del-edificio-azulona","title":"Eevee de la azotea del Edificio Azulona","text":"Cuándo: al llegar a Ciudad Azulona. Dónde: Ciudad Azulona, Edificio Azulona (Mansión Azulona): casa de la azotea, a la que se sube por la puerta trasera. Paso a paso: 1) Rodea el Edificio Azulona y entra por la puerta trasera, en la cara norte. 2) Sube por las escaleras hasta la azotea y entra en la casita que hay arriba. 3) Coge la Poké Ball de la mesa: es Eevee de nivel 25. 4) Evoluciónalo con una de las piedras de la 4.ª planta del Centro Comercial Azulona: Piedra Agua (Vaporeon), Piedra Trueno (Jolteon) o Piedra Fuego (Flareon). Consejo: solo hay un Eevee por partida: elige bien la evolución; las otras dos tienen su bloque en «Completismo y colección». Fuente: decompilación de pret (pokered: scripts/CeladonMansionRoofHouse, data/items/marts); WikiDex («Edificio Azulona»)."},{"key":"pokemon-de-premio-del-casino-rocket","title":"Pokémon de premio del Casino Rocket","text":"Cuándo: desde que llegas a Ciudad Azulona; las fichas se acumulan durante toda la partida. Dónde: Ciudad Azulona: restaurante (Monedero), Casino Rocket (fichas) y tienda de premios, junto al casino. Paso a paso: 1) Entra en el restaurante de Ciudad Azulona y habla con el hombre de la mesa de la esquina: te da el Monedero, sin el que no puedes tener fichas. 2) En el Casino Rocket compra fichas al dependiente (50 fichas por 1000 ₽) o gánalas en las tragaperras; busca también fichas sueltas por el suelo del casino. 3) Ve a la tienda de premios, el local de al lado del casino, y canjea los Pokémon: Abra (180 fichas, nv. 9), Clefairy (500, nv. 8), Nidorina (1200, nv. 17), Dratini (2800, nv. 18), Scyther (5500, nv. 25) y Porygon (9999, nv. 26). 4) En la misma tienda hay MT de premio: MT23 (Furia Dragón, 3300), MT15 (Hiperrayo, 5500) y MT50 (Sustituto, 7700). Consejo: Porygon no aparece en ningún otro sitio del juego; guarda antes de jugar a las tragaperras. Fuente: decompilación de pret (pokered: data/events/prizes, data/events/prize_mon_levels, scripts/CeladonDiner, text/GameCorner); WikiDex («Casino Rocket», «Monedero»)."},{"key":"hitmonlee-o-hitmonchan-del-dojo-karate","title":"Hitmonlee o Hitmonchan del Dojo Karate","text":"Cuándo: al entrar en Ciudad Azafrán (antes o después del gimnasio de Sabrina). Dónde: Ciudad Azafrán, Dojo Karate: el edificio contiguo al gimnasio, también con cartel de gimnasio. Paso a paso: 1) Para entrar en Ciudad Azafrán, da una bebida (Agua Fresca, Refresco o Limonada, de las máquinas de la azotea del Centro Comercial Azulona) a uno de los guardias de las casetas. 2) En el Dojo Karate vence a los cuatro karatekas y al Maestro Karateka del fondo. 3) Coge una de las dos Poké Balls del fondo: Hitmonlee (izquierda) o Hitmonchan (derecha), ambos de nivel 30. Consejo: la otra Poké Ball ya no se puede coger: el Hitmon que dejes tiene su bloque en «Completismo y colección». Fuente: decompilación de pret (pokered: data/maps/objects/FightingDojo, scripts/FightingDojo); WikiDex («Dojo Karate»)."},{"key":"lapras-de-silph-s-a","title":"Lapras de Silph S. A.","text":"Cuándo: durante la toma de Silph S. A. por el Team Rocket (también después). Dónde: Ciudad Azafrán, Silph S. A., 7.ª planta. Paso a paso: 1) Entra en Silph S. A. y sube hasta la 7.ª planta (usa los teletransportadores y la Llave Magnética de la 5.ª planta). 2) Habla con el empleado de Silph de esa planta. 3) Te regala un Lapras de nivel 15; si tienes el equipo lleno, va al PC. Consejo: es el único Lapras del juego. Fuente: decompilación de pret (pokered: scripts/SilphCo7F); WikiDex («Silph S. A.»)."},{"key":"ayudante-de-oak-de-la-ruta-15-repartir-exp-50-especies","title":"Ayudante de Oak de la Ruta 15: Repartir Exp (50 especies)","text":"Cuándo: cuando tengas 50 especies registradas como capturadas. Dónde: Ruta 15, al este de Ciudad Fucsia: puesto de control, planta de arriba. Paso a paso: 1) Comprueba en la Pokédex que tienes al menos 50 especies capturadas. 2) Ve a la Ruta 15 (sal de Ciudad Fucsia por el este) y entra en el puesto de control. 3) Sube a la planta de arriba y habla con el ayudante del profesor Oak: te da el Repartir Exp. Consejo: en esta generación el Repartir Exp reparte la experiencia entre todo el equipo, aunque no combatan. Fuente: decompilación de pret (pokered: scripts/Route15Gate2F); WikiDex («Ruta 15»)."},{"key":"intercambio-del-puesto-de-la-ruta-18-slowbro-por-lickitung","title":"Intercambio del puesto de la Ruta 18: Slowbro por Lickitung","text":"Cuándo: cuando tengas un Slowbro (Slowpoke evoluciona al nivel 37). Dónde: Ruta 18, al oeste de Ciudad Fucsia: puesto de control, planta de arriba. Paso a paso: 1) Consigue un Slowbro: captúralo en las Islas Espuma o sube un Slowpoke al nivel 37. 2) Ve a la Ruta 18 y sube a la planta de arriba del puesto de control. 3) Habla con quien busca un Slowbro y acepta: recibes a Lickitung, que no aparece salvaje en esta edición. Consejo: es la única forma de registrar Lickitung sin intercambiar con otra consola. Fuente: decompilación de pret (pokered: data/events/trades, scripts/Route18Gate2F, data/wild/maps); WikiDex («Ruta 18»)."},{"key":"intercambios-del-laboratorio-de-isla-canela-seel-electrode-y","title":"Intercambios del Laboratorio de Isla Canela: Seel, Electrode y Tangela","text":"Cuándo: al llegar a Isla Canela (Surf desde Pueblo Paleta por la Ruta 21 o desde Ciudad Fucsia por las Rutas 19-20). Dónde: Isla Canela, Laboratorio Pokémon: sala de fósiles (Seel) y sala de intercambios (Electrode y Tangela). Paso a paso: 1) Ponyta por Seel: captura un Ponyta en la Mansión Pokémon de Isla Canela y entrégalo en la sala de fósiles. 2) Raichu por Electrode: evoluciona un Pikachu (Bosque Verde o Central de Energía) con una Piedra Trueno y entrégalo en la sala de intercambios. 3) Venonat por Tangela: captura un Venonat (Rutas 12 a 15 o Zona Safari) y entrégalo en la sala de intercambios. Consejo: Seel, Electrode y Tangela también se pueden capturar (Islas Espuma, Voltorb nivel 30 y Ruta 21), así que estos intercambios son opcionales; guarda otro Pikachu si quieres registrar los dos. Fuente: decompilación de pret (pokered: data/events/trades, scripts/CinnabarLabFossilRoom, scripts/CinnabarLabTradeRoom, data/wild/maps); WikiDex («Isla Canela»)."}],"RED-16":[{"key":"exclusivas-de-rojo-capturalas","title":"Exclusivas de Rojo: captúralas","text":"Cuándo: a lo largo del viaje; repásalo antes de cerrar la Pokédex. Dónde: en las rutas y zonas indicadas en cada paso (las piedras evolutivas se compran en la 4.ª planta del Centro Comercial Azulona). Paso a paso: 1) Repasa en la Pokédex cuáles de estas once te faltan: Ekans (Rutas 4, 8, 9, 10, 11 y 23) y Arbok (nv. 22); Oddish (Rutas 5, 6, 7, 12-15, 24 y 25), Gloom (nv. 21) y Vileplume (Piedra Hoja); Mankey (Rutas 5-8) y Primeape (nv. 28); Growlithe (Rutas 7 y 8, Mansión Pokémon) y Arcanine (Piedra Fuego); Scyther (Zona Safari, zonas centro y este, o tienda de premios) y Electabuzz (Central de Energía). 2) Captura la forma básica en su ruta y evoluciónala por nivel o con la piedra indicada. 3) Guarda un ejemplar de cada una si piensas intercambiarlas por las de la otra edición. Consejo: son tu moneda de cambio para conseguir las exclusivas de Azul (o Verde japonesa). Fuente: decompilación de pret (pokered: data/wild/maps, data/items/marts); WikiDex («Pokémon Rojo y Pokémon Azul»)."},{"key":"exclusivas-de-azul-o-verde-japonesa-por-intercambio","title":"Exclusivas de Azul (o Verde japonesa): por intercambio","text":"Cuándo: en cualquier momento; normalmente al final, con la Pokédex casi llena. Dónde: no aparecen en Rojo: hay que traerlas de Azul (o Verde japonesa), en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy). Paso a paso: 1) Las once que te faltan: Sandshrew, Sandslash, Vulpix, Ninetales, Meowth, Persian, Bellsprout, Weepinbell, Victreebel, Pinsir y Magmar. 2) Queda con alguien que tenga Azul (o Verde japonesa), guarda la partida y entra en la sala de conexión por cable del Centro Pokémon. 3) Intercambia una por una (puedes ofrecer tus exclusivas a cambio) y devuelve lo que solo prestes. 4) Cada especie recibida queda registrada como capturada. Consejo: si recibes solo la forma básica, puedes evolucionarla tú (por nivel o con piedra) para ahorrar intercambios. Con Pokekeep: abre la Librería, busca cada especie que te falte y añádela legal a una caja de esta partida. Fuente: decompilación de pret (pokered: data/wild/maps); WikiDex («Pokémon Rojo y Pokémon Azul»)."},{"key":"los-dos-iniciales-que-no-elegiste","title":"Los dos iniciales que no elegiste","text":"Cuándo: en cualquier momento. Dónde: solo hay un inicial por partida (laboratorio de Oak, Pueblo Paleta): los otros dos llegan por intercambio, en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy). Paso a paso: 1) Mira cuáles te faltan: Bulbasaur, Ivysaur y Venusaur; Charmander, Charmeleon y Charizard; Squirtle, Wartortle y Blastoise. 2) Pide los dos que no tienes a alguien que los haya elegido en su partida y recíbelos por cable. 3) Súbelos de nivel (evolucionan a los niveles 16 y 32 Bulbasaur, 16 y 36 Charmander y Squirtle) para registrar toda la línea. Consejo: con la forma básica basta: el resto lo registras al evolucionarla. Con Pokekeep: abre la Librería, busca Bulbasaur, Charmander o Squirtle y añade los que te falten a una caja de esta partida. Fuente: decompilación de pret (pokered: data/pokemon/evos_moves); WikiDex («Pokémon inicial»)."},{"key":"el-fosil-que-no-elegiste","title":"El fósil que no elegiste","text":"Cuándo: en cualquier momento después del Monte Moon. Dónde: no se puede conseguir en esta partida: llega por intercambio, en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy). Paso a paso: 1) Si elegiste el Fósil Domo te faltan Omanyte y Omastar; si elegiste el Fósil Hélix, Kabuto y Kabutops. 2) Pide a alguien que haya revivido el otro fósil que te lo pase por cable. 3) Súbelo al nivel 40 para registrar su evolución. Consejo: Aerodactyl no entra aquí: sale del Ámbar Viejo, que sí está en todas las partidas. Con Pokekeep: abre la Librería, busca Kabuto u Omanyte (o su evolución) y añádelo a una caja de esta partida. Fuente: decompilación de pret (pokered: data/maps/objects/MtMoonB2F); WikiDex («Monte Moon»)."},{"key":"el-hitmon-que-no-elegiste","title":"El Hitmon que no elegiste","text":"Cuándo: en cualquier momento después del Dojo Karate. Dónde: no se puede conseguir en esta partida: llega por intercambio, en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy). Paso a paso: 1) Si cogiste a Hitmonlee te falta Hitmonchan, y al revés. 2) Pide a alguien que haya elegido el otro que te lo pase por cable. 3) Al recibirlo queda registrado como capturado. Consejo: en esta generación no hay otra forma de conseguirlo en el juego. Con Pokekeep: abre la Librería, busca Hitmonlee o Hitmonchan y añade el que te falte a una caja de esta partida. Fuente: decompilación de pret (pokered: scripts/FightingDojo); WikiDex («Dojo Karate»)."},{"key":"las-otras-dos-evoluciones-de-eevee","title":"Las otras dos evoluciones de Eevee","text":"Cuándo: en cualquier momento después de recoger a Eevee en el Edificio Azulona. Dónde: solo hay un Eevee por partida: las otras dos evoluciones (Vaporeon, Jolteon o Flareon) llegan por intercambio, en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy). Paso a paso: 1) Mira cuáles te faltan entre Vaporeon (Piedra Agua), Jolteon (Piedra Trueno) y Flareon (Piedra Fuego). 2) Pide a alguien que te pase un Eevee o esas evoluciones por cable. 3) Si recibes un Eevee, evoluciónalo con la piedra que corresponda (4.ª planta del Centro Comercial Azulona). Consejo: si pides Eevee sin evolucionar, registras el resto tú mismo con piedras. Con Pokekeep: abre la Librería, busca Vaporeon, Jolteon o Flareon y añade las que te falten a una caja de esta partida. Fuente: decompilación de pret (pokered: scripts/CeladonMansionRoofHouse, data/items/marts); WikiDex («Eevee»)."},{"key":"evoluciones-por-intercambio-alakazam-machamp-golem-y-gengar","title":"Evoluciones por intercambio: Alakazam, Machamp, Golem y Gengar","text":"Cuándo: cuando tengas Kadabra, Machoke, Graveler y Haunter. Dónde: en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy); necesitas una segunda consola y otra partida. Paso a paso: 1) Consigue Kadabra (Abra al nivel 16), Machoke (Machop al nivel 28), Graveler (Geodude al nivel 25) y Haunter (Gastly al nivel 25). 2) Guarda y envíalos por cable a otra partida: evolucionan al llegar a Alakazam, Machamp, Golem y Gengar. 3) Pide que te los devuelvan con otro intercambio: así quedan registrados como capturados en tu Pokédex. Consejo: un Pokémon recibido de los intercambios del juego no evoluciona al llegar; solo evoluciona cuando se intercambia por cable. Con Pokekeep: abre la Librería, busca Alakazam, Machamp, Golem o Gengar y añade los que te falten a una caja de esta partida. Fuente: decompilación de pret (pokered: data/pokemon/evos_moves); WikiDex («Evolución por intercambio»)."},{"goal":"event-0"},{"goal":"battle0"},{"goal":"medal-type"}],"RED-DETAIL1":[{"goal":"pokemon-145"},{"goal":"pokemon-144"},{"goal":"pokemon-146"},{"goal":"postgame"},{"goal":"pokemon-150"}],"GREEN-15":[{"goal":"pokedex"},{"key":"magikarp-del-vendedor-del-monte-moon","title":"Magikarp del vendedor del Monte Moon","text":"Cuándo: antes de cruzar el Monte Moon, con 500 ₽ en el bolsillo. Dónde: Centro Pokémon de la Ruta 4, al pie del Monte Moon (llegas desde Ciudad Plateada por la Ruta 3). Paso a paso: 1) Entra en el Centro Pokémon que hay junto a la entrada del Monte Moon. 2) Habla con el hombre que vende un Magikarp por 500 ₽ y responde que sí. 3) Si no llevas 500 ₽ no te lo vende; puedes volver más tarde, la oferta no caduca. 4) Súbelo al nivel 20 para que evolucione a Gyarados y registra las dos especies. Consejo: solo lo vende una vez y no admite devoluciones; si lo dejas pasar, la Caña Vieja (casa del pescador de Ciudad Carmín) solo pesca Magikarp. Fuente: decompilación de pret (pokered: scripts/MtMoonPokecenter, scripts/VermilionOldRodHouse) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Monte Moon»)."},{"key":"fosil-del-monte-moon-kabuto-u-omanyte","title":"Fósil del Monte Moon: Kabuto u Omanyte","text":"Cuándo: al cruzar el Monte Moon; se revive al llegar a Isla Canela. Dónde: Monte Moon, último sótano (sótano 2), y la sala de fósiles del Laboratorio Pokémon de Isla Canela. Paso a paso: 1) En el último sótano del Monte Moon vence al Supernecio que custodia los dos fósiles. 2) Elige el Fósil Domo (Kabuto) o el Fósil Hélix (Omanyte): el otro ya no se puede coger en esta partida. 3) En Isla Canela entra en el Laboratorio Pokémon, ve a la sala de fósiles y dale el fósil al científico. 4) Sal del laboratorio a la calle, vuelve a entrar y háblale: te entrega Kabuto u Omanyte. 5) Súbelo al nivel 40 para registrar Kabutops u Omastar. Consejo: el científico solo revive un fósil a la vez; el que no elegiste tiene su propio bloque más abajo. Fuente: decompilación de pret (pokered: data/maps/objects/MtMoonB2F, scripts/CinnabarLabFossilRoom, scripts/CinnabarIsland) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Monte Moon»)."},{"key":"intercambio-de-ciudad-celeste-poliwhirl-por-jynx","title":"Intercambio de Ciudad Celeste: Poliwhirl por Jynx","text":"Cuándo: cuando tengas un Poliwhirl; en la práctica, tras conseguir la Caña Buena en Ciudad Fucsia. Dónde: Ciudad Celeste, casa de intercambio. Paso a paso: 1) Pesca un Poliwag con la Caña Buena (te la regala el pescador de Ciudad Fucsia) y súbelo al nivel 25, o pesca un Poliwhirl con la Supercaña (casa de la Ruta 12). 2) Entra en la casa de intercambio de Ciudad Celeste y habla con quien busca un Poliwhirl. 3) Acepta y entrega a tu Poliwhirl: recibes una Jynx, que no aparece salvaje en el juego. Consejo: guarda otro Poliwhirl si también quieres registrar Poliwrath (Piedra Agua). Fuente: decompilación de pret (pokered: data/events/trades, scripts/CeruleanTradeHouse, data/wild/good_rod, scripts/FuchsiaGoodRodHouse) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Ciudad Celeste»)."},{"key":"intercambio-de-la-via-subterranea-nidoran-por-nidoran","title":"Intercambio de la Vía Subterránea: Nidoran♂ por Nidoran♀","text":"Cuándo: en cuanto llegues a la Ruta 5, al sur de Ciudad Celeste. Dónde: Ruta 5: caseta de entrada de la Vía Subterránea. Paso a paso: 1) Captura un Nidoran♂ en la Ruta 22 (al oeste de Ciudad Verde) o en la Zona Safari. 2) Entra en la caseta de la Vía Subterránea de la Ruta 5 y habla con quien busca un Nidoran♂. 3) Acepta: recibes una Nidoran♀. Consejo: Nidoran♀ también sale salvaje en la Ruta 22, así que este intercambio solo te ahorra la captura. Fuente: decompilación de pret (pokered: data/events/trades, scripts/UndergroundPathRoute5, data/wild/maps/Route22) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Vía Subterránea»)."},{"key":"intercambio-de-ciudad-carmin-spearow-por-farfetch-d","title":"Intercambio de Ciudad Carmín: Spearow por Farfetch'd","text":"Cuándo: al llegar a Ciudad Carmín. Dónde: Ciudad Carmín, casa de intercambio. Paso a paso: 1) Captura un Spearow (Rutas 3, 4, 9, 10, 11 o 22, entre otras). 2) Entra en la casa de intercambio de Ciudad Carmín y habla con quien busca un Spearow. 3) Acepta: recibes a Farfetch'd, que no aparece salvaje en esta edición. Consejo: es la única forma de registrar Farfetch'd sin intercambiar con otra consola. Fuente: decompilación de pret (pokered: data/events/trades, scripts/VermilionTradeHouse, data/wild/maps) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Ciudad Carmín»)."},{"key":"intercambio-del-puesto-de-la-ruta-11-nidorino-por-nidorina","title":"Intercambio del puesto de la Ruta 11: Nidorino por Nidorina","text":"Cuándo: cuando tengas un Nidorino (Nidoran♂ evoluciona al nivel 16). Dónde: Ruta 11, al este de Ciudad Carmín: puesto de control, planta de arriba. Paso a paso: 1) Sube un Nidoran♂ al nivel 16 para tener un Nidorino. 2) Entra en el puesto de control de la Ruta 11 y sube a la planta de arriba. 3) Habla con quien busca un Nidorino y acepta: recibes una Nidorina. Consejo: Nidorina también se consigue evolucionando una Nidoran♀ (nv. 16) o en la Zona Safari; usa una Piedra Lunar para Nidoqueen. Fuente: decompilación de pret (pokered: data/events/trades, scripts/Route11Gate2F) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Ruta 11»)."},{"key":"ayudante-de-oak-de-la-ruta-11-buscaobjetos-30-especies","title":"Ayudante de Oak de la Ruta 11: Buscaobjetos (30 especies)","text":"Cuándo: cuando tengas 30 especies registradas como capturadas. Dónde: Ruta 11, puesto de control, planta de arriba. Paso a paso: 1) Comprueba en la Pokédex que tienes al menos 30 especies capturadas. 2) Sube a la planta de arriba del puesto de la Ruta 11 y habla con el ayudante del profesor Oak. 3) Te entrega el Buscaobjetos, que pita cuando hay un objeto oculto cerca. Consejo: si aún no llegas a 30, el ayudante te dice cuántas te faltan; vuelve más tarde. Fuente: decompilación de pret (pokered: scripts/Route11Gate2F) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Zahorí»)."},{"key":"intercambio-de-la-casa-de-la-ruta-2-abra-por-mr-mime","title":"Intercambio de la casa de la Ruta 2: Abra por Mr. Mime","text":"Cuándo: cuando tengas un Abra y acceso a la parte este de la Ruta 2. Dónde: Ruta 2, zona este: casa de intercambio (se llega cruzando la Cueva Diglett desde la Ruta 11 o usando Corte). Paso a paso: 1) Captura un Abra en las Rutas 24 o 25 (huye al primer turno: duérmelo o lanza la Poké Ball enseguida). 2) Cruza la Cueva Diglett desde la Ruta 11 (o corta el arbolito de la Ruta 2) y entra en la casa de intercambio. 3) Habla con quien busca un Abra y acepta: recibes a Mr. Mime, que no aparece salvaje. Consejo: guarda otro Abra para Kadabra y Alakazam. Fuente: decompilación de pret (pokered: data/events/trades, scripts/Route2TradeHouse, data/maps/objects/Route2) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Ruta 2»)."},{"key":"ayudante-de-oak-de-la-ruta-2-mo05-destello-10-especies","title":"Ayudante de Oak de la Ruta 2: MO05 Destello (10 especies)","text":"Cuándo: cuando tengas 10 especies registradas como capturadas. Dónde: Ruta 2, zona este: puesto de control que corta el camino, al sur de la casa de intercambio. Paso a paso: 1) Comprueba en la Pokédex que tienes al menos 10 especies capturadas. 2) Llega a la zona este de la Ruta 2 por la Cueva Diglett (desde la Ruta 11) o con Corte y entra en el puesto de control. 3) Habla con el ayudante del profesor Oak: te da la MO05 (Destello), que ilumina el Túnel Roca (requiere la Medalla Roca). Consejo: conviene recogerla antes de cruzar el Túnel Roca. Fuente: decompilación de pret (pokered: scripts/Route2Gate, data/maps/objects/Route2) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Ruta 2»)."},{"key":"ambar-viejo-aerodactyl","title":"Ámbar Viejo: Aerodactyl","text":"Cuándo: en cuanto puedas usar Corte fuera de combate (MO01 del capitán del S.S. Anne y Medalla Cascada); se revive en Isla Canela. Dónde: Ciudad Plateada, parte trasera del Museo de la Ciencia, y la sala de fósiles del Laboratorio Pokémon de Isla Canela. Paso a paso: 1) Vuelve a Ciudad Plateada y corta el arbolito que da paso a la entrada lateral del Museo de la Ciencia. 2) Entra por esa puerta: el científico de la sala te da el Ámbar Viejo. 3) En Isla Canela entrégalo al científico de la sala de fósiles del Laboratorio Pokémon (si está reviviendo tu otro fósil, recoge ese antes). 4) Sal a la calle, vuelve a entrar y recoge a Aerodactyl. Consejo: el Ámbar Viejo no caduca: puedes revivirlo cuando quieras. Fuente: decompilación de pret (pokered: scripts/Museum1F, scripts/CinnabarLabFossilRoom) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Ámbar Viejo», «Museo de la Ciencia de Ciudad Plateada»)."},{"key":"eevee-de-la-azotea-del-edificio-azulona","title":"Eevee de la azotea del Edificio Azulona","text":"Cuándo: al llegar a Ciudad Azulona. Dónde: Ciudad Azulona, Edificio Azulona (Mansión Azulona): casa de la azotea, a la que se sube por la puerta trasera. Paso a paso: 1) Rodea el Edificio Azulona y entra por la puerta trasera, en la cara norte. 2) Sube por las escaleras hasta la azotea y entra en la casita que hay arriba. 3) Coge la Poké Ball de la mesa: es Eevee. 4) Evoluciónalo con una de las piedras de la 4.ª planta del Centro Comercial Azulona: Piedra Agua (Vaporeon), Piedra Trueno (Jolteon) o Piedra Fuego (Flareon). Consejo: solo hay un Eevee por partida: elige bien la evolución; las otras dos tienen su bloque en «Completismo y colección». Fuente: decompilación de pret (pokered: scripts/CeladonMansionRoofHouse, data/items/marts) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Edificio Azulona»)."},{"key":"pokemon-de-premio-del-casino-rocket","title":"Pokémon de premio del Casino Rocket","text":"Cuándo: desde que llegas a Ciudad Azulona; las fichas se acumulan durante toda la partida. Dónde: Ciudad Azulona: restaurante (Monedero), Casino Rocket (fichas) y tienda de premios, junto al casino. Paso a paso: 1) Entra en el restaurante de Ciudad Azulona y habla con el hombre de la mesa de la esquina: te da el Monedero, sin el que no puedes tener fichas. 2) En el Casino Rocket compra fichas al dependiente (50 fichas por 1000 ₽) o gánalas en las tragaperras; busca también fichas sueltas por el suelo del casino. 3) Ve a la tienda de premios, el local de al lado del casino, y canjea los Pokémon que ofrece: Porygon solo se consigue aquí. 4) En la misma tienda hay MT de premio: MT23 (Furia Dragón, 3300), MT15 (Hiperrayo, 5500) y MT50 (Sustituto, 7700). Consejo: Porygon no aparece en ningún otro sitio del juego; guarda antes de jugar a las tragaperras. La lista exacta de premios y precios de Verde japonesa no se ha podido contrastar: en la tienda verás cuáles son. Fuente: decompilación de pret (pokered: data/events/prizes, data/events/prize_mon_levels, scripts/CeladonDiner, text/GameCorner) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Casino Rocket», «Monedero»)."},{"key":"hitmonlee-o-hitmonchan-del-dojo-karate","title":"Hitmonlee o Hitmonchan del Dojo Karate","text":"Cuándo: al entrar en Ciudad Azafrán (antes o después del gimnasio de Sabrina). Dónde: Ciudad Azafrán, Dojo Karate: el edificio contiguo al gimnasio, también con cartel de gimnasio. Paso a paso: 1) Para entrar en Ciudad Azafrán, da una bebida (Agua Fresca, Refresco o Limonada, de las máquinas de la azotea del Centro Comercial Azulona) a uno de los guardias de las casetas. 2) En el Dojo Karate vence a los cuatro karatekas y al Maestro Karateka del fondo. 3) Coge una de las dos Poké Balls del fondo: Hitmonlee (izquierda) o Hitmonchan (derecha). Consejo: la otra Poké Ball ya no se puede coger: el Hitmon que dejes tiene su bloque en «Completismo y colección». Fuente: decompilación de pret (pokered: data/maps/objects/FightingDojo, scripts/FightingDojo) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Dojo Karate»)."},{"key":"lapras-de-silph-s-a","title":"Lapras de Silph S. A.","text":"Cuándo: durante la toma de Silph S. A. por el Team Rocket (también después). Dónde: Ciudad Azafrán, Silph S. A., 7.ª planta. Paso a paso: 1) Entra en Silph S. A. y sube hasta la 7.ª planta (usa los teletransportadores y la Llave Magnética de la 5.ª planta). 2) Habla con el empleado de Silph de esa planta. 3) Te regala un Lapras; si tienes el equipo lleno, va al PC. Consejo: es el único Lapras del juego. Fuente: decompilación de pret (pokered: scripts/SilphCo7F) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Silph S. A.»)."},{"key":"ayudante-de-oak-de-la-ruta-15-repartir-exp-50-especies","title":"Ayudante de Oak de la Ruta 15: Repartir Exp (50 especies)","text":"Cuándo: cuando tengas 50 especies registradas como capturadas. Dónde: Ruta 15, al este de Ciudad Fucsia: puesto de control, planta de arriba. Paso a paso: 1) Comprueba en la Pokédex que tienes al menos 50 especies capturadas. 2) Ve a la Ruta 15 (sal de Ciudad Fucsia por el este) y entra en el puesto de control. 3) Sube a la planta de arriba y habla con el ayudante del profesor Oak: te da el Repartir Exp. Consejo: en esta generación el Repartir Exp reparte la experiencia entre todo el equipo, aunque no combatan. Fuente: decompilación de pret (pokered: scripts/Route15Gate2F) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Ruta 15»)."},{"key":"intercambio-del-puesto-de-la-ruta-18-slowbro-por-lickitung","title":"Intercambio del puesto de la Ruta 18: Slowbro por Lickitung","text":"Cuándo: cuando tengas un Slowbro (Slowpoke evoluciona al nivel 37). Dónde: Ruta 18, al oeste de Ciudad Fucsia: puesto de control, planta de arriba. Paso a paso: 1) Consigue un Slowbro: captúralo en las Islas Espuma o sube un Slowpoke al nivel 37. 2) Ve a la Ruta 18 y sube a la planta de arriba del puesto de control. 3) Habla con quien busca un Slowbro y acepta: recibes a Lickitung, que no aparece salvaje en esta edición. Consejo: es la única forma de registrar Lickitung sin intercambiar con otra consola. Fuente: decompilación de pret (pokered: data/events/trades, scripts/Route18Gate2F, data/wild/maps) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Ruta 18»)."},{"key":"intercambios-del-laboratorio-de-isla-canela-seel-electrode-y","title":"Intercambios del Laboratorio de Isla Canela: Seel, Electrode y Tangela","text":"Cuándo: al llegar a Isla Canela (Surf desde Pueblo Paleta por la Ruta 21 o desde Ciudad Fucsia por las Rutas 19-20). Dónde: Isla Canela, Laboratorio Pokémon: sala de fósiles (Seel) y sala de intercambios (Electrode y Tangela). Paso a paso: 1) Ponyta por Seel: captura un Ponyta en la Mansión Pokémon de Isla Canela y entrégalo en la sala de fósiles. 2) Raichu por Electrode: evoluciona un Pikachu (Bosque Verde o Central de Energía) con una Piedra Trueno y entrégalo en la sala de intercambios. 3) Venonat por Tangela: captura un Venonat (Rutas 12 a 15 o Zona Safari) y entrégalo en la sala de intercambios. Consejo: Seel, Electrode y Tangela también se pueden capturar (Islas Espuma, Voltorb nivel 30 y Ruta 21), así que estos intercambios son opcionales; guarda otro Pikachu si quieres registrar los dos. Fuente: decompilación de pret (pokered: data/events/trades, scripts/CinnabarLabFossilRoom, scripts/CinnabarLabTradeRoom, data/wild/maps) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Isla Canela»)."}],"GREEN-16":[{"key":"exclusivas-de-verde-capturalas","title":"Exclusivas de Verde: captúralas","text":"Cuándo: a lo largo del viaje; repásalo antes de cerrar la Pokédex. Dónde: en las rutas y zonas indicadas en cada paso (las piedras evolutivas se compran en la 4.ª planta del Centro Comercial Azulona). Paso a paso: 1) Repasa en la Pokédex cuáles de estas once te faltan: Sandshrew (Rutas 4, 8, 9, 10, 11 y 23) y Sandslash (nv. 22); Vulpix (Rutas 7 y 8, Mansión Pokémon) y Ninetales (Piedra Fuego); Meowth (Rutas 5-8) y Persian (nv. 28); Bellsprout (Rutas 5, 6, 7, 12-15, 24 y 25), Weepinbell (nv. 21) y Victreebel (Piedra Hoja); Pinsir (Zona Safari, zonas centro y este) y Magmar (Mansión Pokémon, 3.ª planta y sótano). 2) Captura la forma básica en su ruta y evoluciónala por nivel o con la piedra indicada. 3) Guarda un ejemplar de cada una si piensas intercambiarlas por las de la otra edición. Consejo: son tu moneda de cambio para conseguir las exclusivas de Rojo. Fuente: decompilación de pret (pokered: data/wild/maps, data/items/marts) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Pokémon Rojo y Pokémon Azul»)."},{"key":"exclusivas-de-rojo-por-intercambio","title":"Exclusivas de Rojo: por intercambio","text":"Cuándo: en cualquier momento; normalmente al final, con la Pokédex casi llena. Dónde: no aparecen en Verde: hay que traerlas de Rojo, en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy). Paso a paso: 1) Las once que te faltan: Ekans, Arbok, Oddish, Gloom, Vileplume, Mankey, Primeape, Growlithe, Arcanine, Scyther y Electabuzz. 2) Queda con alguien que tenga Rojo, guarda la partida y entra en la sala de conexión por cable del Centro Pokémon. 3) Intercambia una por una (puedes ofrecer tus exclusivas a cambio) y devuelve lo que solo prestes. 4) Cada especie recibida queda registrada como capturada. Consejo: si recibes solo la forma básica, puedes evolucionarla tú (por nivel o con piedra) para ahorrar intercambios. Con Pokekeep: abre la Librería, busca cada especie que te falte y añádela legal a una caja de esta partida. Fuente: decompilación de pret (pokered: data/wild/maps) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Pokémon Rojo y Pokémon Azul»)."},{"key":"los-dos-iniciales-que-no-elegiste","title":"Los dos iniciales que no elegiste","text":"Cuándo: en cualquier momento. Dónde: solo hay un inicial por partida (laboratorio de Oak, Pueblo Paleta): los otros dos llegan por intercambio, en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy). Paso a paso: 1) Mira cuáles te faltan: Bulbasaur, Ivysaur y Venusaur; Charmander, Charmeleon y Charizard; Squirtle, Wartortle y Blastoise. 2) Pide los dos que no tienes a alguien que los haya elegido en su partida y recíbelos por cable. 3) Súbelos de nivel (evolucionan a los niveles 16 y 32 Bulbasaur, 16 y 36 Charmander y Squirtle) para registrar toda la línea. Consejo: con la forma básica basta: el resto lo registras al evolucionarla. Con Pokekeep: abre la Librería, busca Bulbasaur, Charmander o Squirtle y añade los que te falten a una caja de esta partida. Fuente: decompilación de pret (pokered: data/pokemon/evos_moves) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Pokémon inicial»)."},{"key":"el-fosil-que-no-elegiste","title":"El fósil que no elegiste","text":"Cuándo: en cualquier momento después del Monte Moon. Dónde: no se puede conseguir en esta partida: llega por intercambio, en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy). Paso a paso: 1) Si elegiste el Fósil Domo te faltan Omanyte y Omastar; si elegiste el Fósil Hélix, Kabuto y Kabutops. 2) Pide a alguien que haya revivido el otro fósil que te lo pase por cable. 3) Súbelo al nivel 40 para registrar su evolución. Consejo: Aerodactyl no entra aquí: sale del Ámbar Viejo, que sí está en todas las partidas. Con Pokekeep: abre la Librería, busca Kabuto u Omanyte (o su evolución) y añádelo a una caja de esta partida. Fuente: decompilación de pret (pokered: data/maps/objects/MtMoonB2F) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Monte Moon»)."},{"key":"el-hitmon-que-no-elegiste","title":"El Hitmon que no elegiste","text":"Cuándo: en cualquier momento después del Dojo Karate. Dónde: no se puede conseguir en esta partida: llega por intercambio, en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy). Paso a paso: 1) Si cogiste a Hitmonlee te falta Hitmonchan, y al revés. 2) Pide a alguien que haya elegido el otro que te lo pase por cable. 3) Al recibirlo queda registrado como capturado. Consejo: en esta generación no hay otra forma de conseguirlo en el juego. Con Pokekeep: abre la Librería, busca Hitmonlee o Hitmonchan y añade el que te falte a una caja de esta partida. Fuente: decompilación de pret (pokered: scripts/FightingDojo) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Dojo Karate»)."},{"key":"las-otras-dos-evoluciones-de-eevee","title":"Las otras dos evoluciones de Eevee","text":"Cuándo: en cualquier momento después de recoger a Eevee en el Edificio Azulona. Dónde: solo hay un Eevee por partida: las otras dos evoluciones (Vaporeon, Jolteon o Flareon) llegan por intercambio, en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy). Paso a paso: 1) Mira cuáles te faltan entre Vaporeon (Piedra Agua), Jolteon (Piedra Trueno) y Flareon (Piedra Fuego). 2) Pide a alguien que te pase un Eevee o esas evoluciones por cable. 3) Si recibes un Eevee, evoluciónalo con la piedra que corresponda (4.ª planta del Centro Comercial Azulona). Consejo: si pides Eevee sin evolucionar, registras el resto tú mismo con piedras. Con Pokekeep: abre la Librería, busca Vaporeon, Jolteon o Flareon y añade las que te falten a una caja de esta partida. Fuente: decompilación de pret (pokered: scripts/CeladonMansionRoofHouse, data/items/marts) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Eevee»)."},{"key":"evoluciones-por-intercambio-alakazam-machamp-golem-y-gengar","title":"Evoluciones por intercambio: Alakazam, Machamp, Golem y Gengar","text":"Cuándo: cuando tengas Kadabra, Machoke, Graveler y Haunter. Dónde: en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy); necesitas una segunda consola y otra partida. Paso a paso: 1) Consigue Kadabra (Abra al nivel 16), Machoke (Machop al nivel 28), Graveler (Geodude al nivel 25) y Haunter (Gastly al nivel 25). 2) Guarda y envíalos por cable a otra partida: evolucionan al llegar a Alakazam, Machamp, Golem y Gengar. 3) Pide que te los devuelvan con otro intercambio: así quedan registrados como capturados en tu Pokédex. Consejo: un Pokémon recibido de los intercambios del juego no evoluciona al llegar; solo evoluciona cuando se intercambia por cable. Con Pokekeep: abre la Librería, busca Alakazam, Machamp, Golem o Gengar y añade los que te falten a una caja de esta partida. Fuente: decompilación de pret (pokered: data/pokemon/evos_moves) (edición occidental equivalente: no hay decompilación de Verde japonesa); WikiDex («Evolución por intercambio»)."},{"goal":"event-0"},{"goal":"battle0"},{"goal":"medal-type"}],"GREEN-DETAIL1":[{"goal":"pokemon-145"},{"goal":"pokemon-144"},{"goal":"pokemon-146"},{"goal":"postgame"},{"goal":"pokemon-150"}],"BLUE-15":[{"goal":"pokedex"},{"key":"magikarp-del-vendedor-del-monte-moon","title":"Magikarp del vendedor del Monte Moon","text":"Cuándo: antes de cruzar el Monte Moon, con 500 ₽ en el bolsillo. Dónde: Centro Pokémon de la Ruta 4, al pie del Monte Moon (llegas desde Ciudad Plateada por la Ruta 3). Paso a paso: 1) Entra en el Centro Pokémon que hay junto a la entrada del Monte Moon. 2) Habla con el hombre que vende un Magikarp de nivel 5 por 500 ₽ y responde que sí. 3) Si no llevas 500 ₽ no te lo vende; puedes volver más tarde, la oferta no caduca. 4) Súbelo al nivel 20 para que evolucione a Gyarados y registra las dos especies. Consejo: solo lo vende una vez y no admite devoluciones; si lo dejas pasar, la Caña Vieja (casa del pescador de Ciudad Carmín) solo pesca Magikarp. Fuente: decompilación de pret (pokered: scripts/MtMoonPokecenter, scripts/VermilionOldRodHouse); WikiDex («Monte Moon»)."},{"key":"fosil-del-monte-moon-kabuto-u-omanyte","title":"Fósil del Monte Moon: Kabuto u Omanyte","text":"Cuándo: al cruzar el Monte Moon; se revive al llegar a Isla Canela. Dónde: Monte Moon, último sótano (sótano 2), y la sala de fósiles del Laboratorio Pokémon de Isla Canela. Paso a paso: 1) En el último sótano del Monte Moon vence al Supernecio que custodia los dos fósiles. 2) Elige el Fósil Domo (Kabuto) o el Fósil Hélix (Omanyte): el otro ya no se puede coger en esta partida. 3) En Isla Canela entra en el Laboratorio Pokémon, ve a la sala de fósiles y dale el fósil al científico. 4) Sal del laboratorio a la calle, vuelve a entrar y háblale: te entrega Kabuto u Omanyte de nivel 30. 5) Súbelo al nivel 40 para registrar Kabutops u Omastar. Consejo: el científico solo revive un fósil a la vez; el que no elegiste tiene su propio bloque más abajo. Fuente: decompilación de pret (pokered: data/maps/objects/MtMoonB2F, scripts/CinnabarLabFossilRoom, scripts/CinnabarIsland); WikiDex («Monte Moon»)."},{"key":"intercambio-de-ciudad-celeste-poliwhirl-por-jynx","title":"Intercambio de Ciudad Celeste: Poliwhirl por Jynx","text":"Cuándo: cuando tengas un Poliwhirl; en la práctica, tras conseguir la Caña Buena en Ciudad Fucsia. Dónde: Ciudad Celeste, casa de intercambio. Paso a paso: 1) Pesca un Poliwag con la Caña Buena (te la regala el pescador de Ciudad Fucsia) y súbelo al nivel 25, o pesca un Poliwhirl con la Supercaña (casa de la Ruta 12). 2) Entra en la casa de intercambio de Ciudad Celeste y habla con quien busca un Poliwhirl. 3) Acepta y entrega a tu Poliwhirl: recibes una Jynx, que no aparece salvaje en el juego. Consejo: guarda otro Poliwhirl si también quieres registrar Poliwrath (Piedra Agua). Fuente: decompilación de pret (pokered: data/events/trades, scripts/CeruleanTradeHouse, data/wild/good_rod, scripts/FuchsiaGoodRodHouse); WikiDex («Ciudad Celeste»)."},{"key":"intercambio-de-la-via-subterranea-nidoran-por-nidoran","title":"Intercambio de la Vía Subterránea: Nidoran♂ por Nidoran♀","text":"Cuándo: en cuanto llegues a la Ruta 5, al sur de Ciudad Celeste. Dónde: Ruta 5: caseta de entrada de la Vía Subterránea. Paso a paso: 1) Captura un Nidoran♂ en la Ruta 22 (al oeste de Ciudad Verde) o en la Zona Safari. 2) Entra en la caseta de la Vía Subterránea de la Ruta 5 y habla con quien busca un Nidoran♂. 3) Acepta: recibes una Nidoran♀. Consejo: Nidoran♀ también sale salvaje en la Ruta 22, así que este intercambio solo te ahorra la captura. Fuente: decompilación de pret (pokered: data/events/trades, scripts/UndergroundPathRoute5, data/wild/maps/Route22); WikiDex («Vía Subterránea»)."},{"key":"intercambio-de-ciudad-carmin-spearow-por-farfetch-d","title":"Intercambio de Ciudad Carmín: Spearow por Farfetch'd","text":"Cuándo: al llegar a Ciudad Carmín. Dónde: Ciudad Carmín, casa de intercambio. Paso a paso: 1) Captura un Spearow (Rutas 3, 4, 9, 10, 11 o 22, entre otras). 2) Entra en la casa de intercambio de Ciudad Carmín y habla con quien busca un Spearow. 3) Acepta: recibes a Farfetch'd, que no aparece salvaje en esta edición. Consejo: es la única forma de registrar Farfetch'd sin intercambiar con otra consola. Fuente: decompilación de pret (pokered: data/events/trades, scripts/VermilionTradeHouse, data/wild/maps); WikiDex («Ciudad Carmín»)."},{"key":"intercambio-del-puesto-de-la-ruta-11-nidorino-por-nidorina","title":"Intercambio del puesto de la Ruta 11: Nidorino por Nidorina","text":"Cuándo: cuando tengas un Nidorino (Nidoran♂ evoluciona al nivel 16). Dónde: Ruta 11, al este de Ciudad Carmín: puesto de control, planta de arriba. Paso a paso: 1) Sube un Nidoran♂ al nivel 16 para tener un Nidorino. 2) Entra en el puesto de control de la Ruta 11 y sube a la planta de arriba. 3) Habla con quien busca un Nidorino y acepta: recibes una Nidorina. Consejo: Nidorina también se consigue evolucionando una Nidoran♀ (nv. 16) o en la Zona Safari; usa una Piedra Lunar para Nidoqueen. Fuente: decompilación de pret (pokered: data/events/trades, scripts/Route11Gate2F); WikiDex («Ruta 11»)."},{"key":"ayudante-de-oak-de-la-ruta-11-buscaobjetos-30-especies","title":"Ayudante de Oak de la Ruta 11: Buscaobjetos (30 especies)","text":"Cuándo: cuando tengas 30 especies registradas como capturadas. Dónde: Ruta 11, puesto de control, planta de arriba. Paso a paso: 1) Comprueba en la Pokédex que tienes al menos 30 especies capturadas. 2) Sube a la planta de arriba del puesto de la Ruta 11 y habla con el ayudante del profesor Oak. 3) Te entrega el Buscaobjetos, que pita cuando hay un objeto oculto cerca. Consejo: si aún no llegas a 30, el ayudante te dice cuántas te faltan; vuelve más tarde. Fuente: decompilación de pret (pokered: scripts/Route11Gate2F); WikiDex («Zahorí»)."},{"key":"intercambio-de-la-casa-de-la-ruta-2-abra-por-mr-mime","title":"Intercambio de la casa de la Ruta 2: Abra por Mr. Mime","text":"Cuándo: cuando tengas un Abra y acceso a la parte este de la Ruta 2. Dónde: Ruta 2, zona este: casa de intercambio (se llega cruzando la Cueva Diglett desde la Ruta 11 o usando Corte). Paso a paso: 1) Captura un Abra en las Rutas 24 o 25 (huye al primer turno: duérmelo o lanza la Poké Ball enseguida). 2) Cruza la Cueva Diglett desde la Ruta 11 (o corta el arbolito de la Ruta 2) y entra en la casa de intercambio. 3) Habla con quien busca un Abra y acepta: recibes a Mr. Mime, que no aparece salvaje. Consejo: guarda otro Abra para Kadabra y Alakazam. Fuente: decompilación de pret (pokered: data/events/trades, scripts/Route2TradeHouse, data/maps/objects/Route2); WikiDex («Ruta 2»)."},{"key":"ayudante-de-oak-de-la-ruta-2-mo05-destello-10-especies","title":"Ayudante de Oak de la Ruta 2: MO05 Destello (10 especies)","text":"Cuándo: cuando tengas 10 especies registradas como capturadas. Dónde: Ruta 2, zona este: puesto de control que corta el camino, al sur de la casa de intercambio. Paso a paso: 1) Comprueba en la Pokédex que tienes al menos 10 especies capturadas. 2) Llega a la zona este de la Ruta 2 por la Cueva Diglett (desde la Ruta 11) o con Corte y entra en el puesto de control. 3) Habla con el ayudante del profesor Oak: te da la MO05 (Destello), que ilumina el Túnel Roca (requiere la Medalla Roca). Consejo: conviene recogerla antes de cruzar el Túnel Roca. Fuente: decompilación de pret (pokered: scripts/Route2Gate, data/maps/objects/Route2); WikiDex («Ruta 2»)."},{"key":"ambar-viejo-aerodactyl","title":"Ámbar Viejo: Aerodactyl","text":"Cuándo: en cuanto puedas usar Corte fuera de combate (MO01 del capitán del S.S. Anne y Medalla Cascada); se revive en Isla Canela. Dónde: Ciudad Plateada, parte trasera del Museo de la Ciencia, y la sala de fósiles del Laboratorio Pokémon de Isla Canela. Paso a paso: 1) Vuelve a Ciudad Plateada y corta el arbolito que da paso a la entrada lateral del Museo de la Ciencia. 2) Entra por esa puerta: el científico de la sala te da el Ámbar Viejo. 3) En Isla Canela entrégalo al científico de la sala de fósiles del Laboratorio Pokémon (si está reviviendo tu otro fósil, recoge ese antes). 4) Sal a la calle, vuelve a entrar y recoge a Aerodactyl de nivel 30. Consejo: el Ámbar Viejo no caduca: puedes revivirlo cuando quieras. Fuente: decompilación de pret (pokered: scripts/Museum1F, scripts/CinnabarLabFossilRoom); WikiDex («Ámbar Viejo», «Museo de la Ciencia de Ciudad Plateada»)."},{"key":"eevee-de-la-azotea-del-edificio-azulona","title":"Eevee de la azotea del Edificio Azulona","text":"Cuándo: al llegar a Ciudad Azulona. Dónde: Ciudad Azulona, Edificio Azulona (Mansión Azulona): casa de la azotea, a la que se sube por la puerta trasera. Paso a paso: 1) Rodea el Edificio Azulona y entra por la puerta trasera, en la cara norte. 2) Sube por las escaleras hasta la azotea y entra en la casita que hay arriba. 3) Coge la Poké Ball de la mesa: es Eevee de nivel 25. 4) Evoluciónalo con una de las piedras de la 4.ª planta del Centro Comercial Azulona: Piedra Agua (Vaporeon), Piedra Trueno (Jolteon) o Piedra Fuego (Flareon). Consejo: solo hay un Eevee por partida: elige bien la evolución; las otras dos tienen su bloque en «Completismo y colección». Fuente: decompilación de pret (pokered: scripts/CeladonMansionRoofHouse, data/items/marts); WikiDex («Edificio Azulona»)."},{"key":"pokemon-de-premio-del-casino-rocket","title":"Pokémon de premio del Casino Rocket","text":"Cuándo: desde que llegas a Ciudad Azulona; las fichas se acumulan durante toda la partida. Dónde: Ciudad Azulona: restaurante (Monedero), Casino Rocket (fichas) y tienda de premios, junto al casino. Paso a paso: 1) Entra en el restaurante de Ciudad Azulona y habla con el hombre de la mesa de la esquina: te da el Monedero, sin el que no puedes tener fichas. 2) En el Casino Rocket compra fichas al dependiente (50 fichas por 1000 ₽) o gánalas en las tragaperras; busca también fichas sueltas por el suelo del casino. 3) Ve a la tienda de premios, el local de al lado del casino, y canjea los Pokémon: Abra (120 fichas, nv. 6), Clefairy (750, nv. 12), Nidorino (1200, nv. 17), Pinsir (2500, nv. 20), Dratini (4600, nv. 24) y Porygon (6500, nv. 18). 4) En la misma tienda hay MT de premio: MT23 (Furia Dragón, 3300), MT15 (Hiperrayo, 5500) y MT50 (Sustituto, 7700). Consejo: Porygon no aparece en ningún otro sitio del juego; guarda antes de jugar a las tragaperras. Fuente: decompilación de pret (pokered: data/events/prizes, data/events/prize_mon_levels, scripts/CeladonDiner, text/GameCorner); WikiDex («Casino Rocket», «Monedero»)."},{"key":"hitmonlee-o-hitmonchan-del-dojo-karate","title":"Hitmonlee o Hitmonchan del Dojo Karate","text":"Cuándo: al entrar en Ciudad Azafrán (antes o después del gimnasio de Sabrina). Dónde: Ciudad Azafrán, Dojo Karate: el edificio contiguo al gimnasio, también con cartel de gimnasio. Paso a paso: 1) Para entrar en Ciudad Azafrán, da una bebida (Agua Fresca, Refresco o Limonada, de las máquinas de la azotea del Centro Comercial Azulona) a uno de los guardias de las casetas. 2) En el Dojo Karate vence a los cuatro karatekas y al Maestro Karateka del fondo. 3) Coge una de las dos Poké Balls del fondo: Hitmonlee (izquierda) o Hitmonchan (derecha), ambos de nivel 30. Consejo: la otra Poké Ball ya no se puede coger: el Hitmon que dejes tiene su bloque en «Completismo y colección». Fuente: decompilación de pret (pokered: data/maps/objects/FightingDojo, scripts/FightingDojo); WikiDex («Dojo Karate»)."},{"key":"lapras-de-silph-s-a","title":"Lapras de Silph S. A.","text":"Cuándo: durante la toma de Silph S. A. por el Team Rocket (también después). Dónde: Ciudad Azafrán, Silph S. A., 7.ª planta. Paso a paso: 1) Entra en Silph S. A. y sube hasta la 7.ª planta (usa los teletransportadores y la Llave Magnética de la 5.ª planta). 2) Habla con el empleado de Silph de esa planta. 3) Te regala un Lapras de nivel 15; si tienes el equipo lleno, va al PC. Consejo: es el único Lapras del juego. Fuente: decompilación de pret (pokered: scripts/SilphCo7F); WikiDex («Silph S. A.»)."},{"key":"ayudante-de-oak-de-la-ruta-15-repartir-exp-50-especies","title":"Ayudante de Oak de la Ruta 15: Repartir Exp (50 especies)","text":"Cuándo: cuando tengas 50 especies registradas como capturadas. Dónde: Ruta 15, al este de Ciudad Fucsia: puesto de control, planta de arriba. Paso a paso: 1) Comprueba en la Pokédex que tienes al menos 50 especies capturadas. 2) Ve a la Ruta 15 (sal de Ciudad Fucsia por el este) y entra en el puesto de control. 3) Sube a la planta de arriba y habla con el ayudante del profesor Oak: te da el Repartir Exp. Consejo: en esta generación el Repartir Exp reparte la experiencia entre todo el equipo, aunque no combatan. Fuente: decompilación de pret (pokered: scripts/Route15Gate2F); WikiDex («Ruta 15»)."},{"key":"intercambio-del-puesto-de-la-ruta-18-slowbro-por-lickitung","title":"Intercambio del puesto de la Ruta 18: Slowbro por Lickitung","text":"Cuándo: cuando tengas un Slowbro (Slowpoke evoluciona al nivel 37). Dónde: Ruta 18, al oeste de Ciudad Fucsia: puesto de control, planta de arriba. Paso a paso: 1) Consigue un Slowbro: captúralo en las Islas Espuma o sube un Slowpoke al nivel 37. 2) Ve a la Ruta 18 y sube a la planta de arriba del puesto de control. 3) Habla con quien busca un Slowbro y acepta: recibes a Lickitung, que no aparece salvaje en esta edición. Consejo: es la única forma de registrar Lickitung sin intercambiar con otra consola. Fuente: decompilación de pret (pokered: data/events/trades, scripts/Route18Gate2F, data/wild/maps); WikiDex («Ruta 18»)."},{"key":"intercambios-del-laboratorio-de-isla-canela-seel-electrode-y","title":"Intercambios del Laboratorio de Isla Canela: Seel, Electrode y Tangela","text":"Cuándo: al llegar a Isla Canela (Surf desde Pueblo Paleta por la Ruta 21 o desde Ciudad Fucsia por las Rutas 19-20). Dónde: Isla Canela, Laboratorio Pokémon: sala de fósiles (Seel) y sala de intercambios (Electrode y Tangela). Paso a paso: 1) Ponyta por Seel: captura un Ponyta en la Mansión Pokémon de Isla Canela y entrégalo en la sala de fósiles. 2) Raichu por Electrode: evoluciona un Pikachu (Bosque Verde o Central de Energía) con una Piedra Trueno y entrégalo en la sala de intercambios. 3) Venonat por Tangela: captura un Venonat (Rutas 12 a 15 o Zona Safari) y entrégalo en la sala de intercambios. Consejo: Seel, Electrode y Tangela también se pueden capturar (Islas Espuma, Voltorb nivel 30 y Ruta 21), así que estos intercambios son opcionales; guarda otro Pikachu si quieres registrar los dos. Fuente: decompilación de pret (pokered: data/events/trades, scripts/CinnabarLabFossilRoom, scripts/CinnabarLabTradeRoom, data/wild/maps); WikiDex («Isla Canela»)."}],"BLUE-16":[{"key":"exclusivas-de-azul-capturalas","title":"Exclusivas de Azul: captúralas","text":"Cuándo: a lo largo del viaje; repásalo antes de cerrar la Pokédex. Dónde: en las rutas y zonas indicadas en cada paso (las piedras evolutivas se compran en la 4.ª planta del Centro Comercial Azulona). Paso a paso: 1) Repasa en la Pokédex cuáles de estas once te faltan: Sandshrew (Rutas 4, 8, 9, 10, 11 y 23) y Sandslash (nv. 22); Vulpix (Rutas 7 y 8, Mansión Pokémon) y Ninetales (Piedra Fuego); Meowth (Rutas 5-8) y Persian (nv. 28); Bellsprout (Rutas 5, 6, 7, 12-15, 24 y 25), Weepinbell (nv. 21) y Victreebel (Piedra Hoja); Pinsir (Zona Safari, zonas centro y este, o tienda de premios) y Magmar (Mansión Pokémon, 3.ª planta y sótano). 2) Captura la forma básica en su ruta y evoluciónala por nivel o con la piedra indicada. 3) Guarda un ejemplar de cada una si piensas intercambiarlas por las de la otra edición. Consejo: son tu moneda de cambio para conseguir las exclusivas de Rojo. Fuente: decompilación de pret (pokered: data/wild/maps, data/items/marts); WikiDex («Pokémon Rojo y Pokémon Azul»)."},{"key":"exclusivas-de-rojo-por-intercambio","title":"Exclusivas de Rojo: por intercambio","text":"Cuándo: en cualquier momento; normalmente al final, con la Pokédex casi llena. Dónde: no aparecen en Azul: hay que traerlas de Rojo, en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy). Paso a paso: 1) Las once que te faltan: Ekans, Arbok, Oddish, Gloom, Vileplume, Mankey, Primeape, Growlithe, Arcanine, Scyther y Electabuzz. 2) Queda con alguien que tenga Rojo, guarda la partida y entra en la sala de conexión por cable del Centro Pokémon. 3) Intercambia una por una (puedes ofrecer tus exclusivas a cambio) y devuelve lo que solo prestes. 4) Cada especie recibida queda registrada como capturada. Consejo: si recibes solo la forma básica, puedes evolucionarla tú (por nivel o con piedra) para ahorrar intercambios. Con Pokekeep: abre la Librería, busca cada especie que te falte y añádela legal a una caja de esta partida. Fuente: decompilación de pret (pokered: data/wild/maps); WikiDex («Pokémon Rojo y Pokémon Azul»)."},{"key":"los-dos-iniciales-que-no-elegiste","title":"Los dos iniciales que no elegiste","text":"Cuándo: en cualquier momento. Dónde: solo hay un inicial por partida (laboratorio de Oak, Pueblo Paleta): los otros dos llegan por intercambio, en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy). Paso a paso: 1) Mira cuáles te faltan: Bulbasaur, Ivysaur y Venusaur; Charmander, Charmeleon y Charizard; Squirtle, Wartortle y Blastoise. 2) Pide los dos que no tienes a alguien que los haya elegido en su partida y recíbelos por cable. 3) Súbelos de nivel (evolucionan a los niveles 16 y 32 Bulbasaur, 16 y 36 Charmander y Squirtle) para registrar toda la línea. Consejo: con la forma básica basta: el resto lo registras al evolucionarla. Con Pokekeep: abre la Librería, busca Bulbasaur, Charmander o Squirtle y añade los que te falten a una caja de esta partida. Fuente: decompilación de pret (pokered: data/pokemon/evos_moves); WikiDex («Pokémon inicial»)."},{"key":"el-fosil-que-no-elegiste","title":"El fósil que no elegiste","text":"Cuándo: en cualquier momento después del Monte Moon. Dónde: no se puede conseguir en esta partida: llega por intercambio, en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy). Paso a paso: 1) Si elegiste el Fósil Domo te faltan Omanyte y Omastar; si elegiste el Fósil Hélix, Kabuto y Kabutops. 2) Pide a alguien que haya revivido el otro fósil que te lo pase por cable. 3) Súbelo al nivel 40 para registrar su evolución. Consejo: Aerodactyl no entra aquí: sale del Ámbar Viejo, que sí está en todas las partidas. Con Pokekeep: abre la Librería, busca Kabuto u Omanyte (o su evolución) y añádelo a una caja de esta partida. Fuente: decompilación de pret (pokered: data/maps/objects/MtMoonB2F); WikiDex («Monte Moon»)."},{"key":"el-hitmon-que-no-elegiste","title":"El Hitmon que no elegiste","text":"Cuándo: en cualquier momento después del Dojo Karate. Dónde: no se puede conseguir en esta partida: llega por intercambio, en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy). Paso a paso: 1) Si cogiste a Hitmonlee te falta Hitmonchan, y al revés. 2) Pide a alguien que haya elegido el otro que te lo pase por cable. 3) Al recibirlo queda registrado como capturado. Consejo: en esta generación no hay otra forma de conseguirlo en el juego. Con Pokekeep: abre la Librería, busca Hitmonlee o Hitmonchan y añade el que te falte a una caja de esta partida. Fuente: decompilación de pret (pokered: scripts/FightingDojo); WikiDex («Dojo Karate»)."},{"key":"las-otras-dos-evoluciones-de-eevee","title":"Las otras dos evoluciones de Eevee","text":"Cuándo: en cualquier momento después de recoger a Eevee en el Edificio Azulona. Dónde: solo hay un Eevee por partida: las otras dos evoluciones (Vaporeon, Jolteon o Flareon) llegan por intercambio, en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy). Paso a paso: 1) Mira cuáles te faltan entre Vaporeon (Piedra Agua), Jolteon (Piedra Trueno) y Flareon (Piedra Fuego). 2) Pide a alguien que te pase un Eevee o esas evoluciones por cable. 3) Si recibes un Eevee, evoluciónalo con la piedra que corresponda (4.ª planta del Centro Comercial Azulona). Consejo: si pides Eevee sin evolucionar, registras el resto tú mismo con piedras. Con Pokekeep: abre la Librería, busca Vaporeon, Jolteon o Flareon y añade las que te falten a una caja de esta partida. Fuente: decompilación de pret (pokered: scripts/CeladonMansionRoofHouse, data/items/marts); WikiDex («Eevee»)."},{"key":"evoluciones-por-intercambio-alakazam-machamp-golem-y-gengar","title":"Evoluciones por intercambio: Alakazam, Machamp, Golem y Gengar","text":"Cuándo: cuando tengas Kadabra, Machoke, Graveler y Haunter. Dónde: en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy); necesitas una segunda consola y otra partida. Paso a paso: 1) Consigue Kadabra (Abra al nivel 16), Machoke (Machop al nivel 28), Graveler (Geodude al nivel 25) y Haunter (Gastly al nivel 25). 2) Guarda y envíalos por cable a otra partida: evolucionan al llegar a Alakazam, Machamp, Golem y Gengar. 3) Pide que te los devuelvan con otro intercambio: así quedan registrados como capturados en tu Pokédex. Consejo: un Pokémon recibido de los intercambios del juego no evoluciona al llegar; solo evoluciona cuando se intercambia por cable. Con Pokekeep: abre la Librería, busca Alakazam, Machamp, Golem o Gengar y añade los que te falten a una caja de esta partida. Fuente: decompilación de pret (pokered: data/pokemon/evos_moves); WikiDex («Evolución por intercambio»)."},{"goal":"event-0"},{"goal":"battle0"},{"goal":"medal-type"}],"BLUE-DETAIL1":[{"goal":"pokemon-145"},{"goal":"pokemon-144"},{"goal":"pokemon-146"},{"goal":"postgame"},{"goal":"pokemon-150"}],"YELLOW-15":[{"goal":"pokedex"},{"key":"magikarp-del-vendedor-del-monte-moon","title":"Magikarp del vendedor del Monte Moon","text":"Cuándo: antes de cruzar el Monte Moon, con 500 ₽ en el bolsillo. Dónde: Centro Pokémon de la Ruta 4, al pie del Monte Moon (llegas desde Ciudad Plateada por la Ruta 3). Paso a paso: 1) Entra en el Centro Pokémon que hay junto a la entrada del Monte Moon. 2) Habla con el hombre que vende un Magikarp de nivel 5 por 500 ₽ y responde que sí. 3) Si no llevas 500 ₽ no te lo vende; puedes volver más tarde, la oferta no caduca. 4) Súbelo al nivel 20 para que evolucione a Gyarados y registra las dos especies. Consejo: solo lo vende una vez y no admite devoluciones; si lo dejas pasar, la Caña Vieja (casa del pescador de Ciudad Carmín) solo pesca Magikarp. Fuente: decompilación de pret (pokeyellow: scripts/MtMoonPokecenter, scripts/VermilionOldRodHouse); WikiDex («Monte Moon»)."},{"key":"fosil-del-monte-moon-kabuto-u-omanyte","title":"Fósil del Monte Moon: Kabuto u Omanyte","text":"Cuándo: al cruzar el Monte Moon; se revive al llegar a Isla Canela. Dónde: Monte Moon, último sótano (sótano 2), y la sala de fósiles del Laboratorio Pokémon de Isla Canela. Paso a paso: 1) En el último sótano del Monte Moon vence al Supernecio que custodia los dos fósiles. 2) Elige el Fósil Domo (Kabuto) o el Fósil Hélix (Omanyte): el otro ya no se puede coger en esta partida. 3) En Isla Canela entra en el Laboratorio Pokémon, ve a la sala de fósiles y dale el fósil al científico. 4) Sal del laboratorio a la calle, vuelve a entrar y háblale: te entrega Kabuto u Omanyte de nivel 30. 5) Súbelo al nivel 40 para registrar Kabutops u Omastar. Consejo: el científico solo revive un fósil a la vez; el que no elegiste tiene su propio bloque más abajo. Fuente: decompilación de pret (pokeyellow: data/maps/objects/MtMoonB2F, scripts/CinnabarLabFossilRoom, scripts/CinnabarIsland); WikiDex («Monte Moon»)."},{"key":"bulbasaur-de-regalo-en-ciudad-celeste","title":"Bulbasaur de regalo en Ciudad Celeste","text":"Cuándo: en cuanto tu Pikachu esté muy contento contigo (amistad 147 o más); se puede volver cuando quieras. Dónde: Ciudad Celeste, casa de Melanie (la chica que cuida a Pokémon abandonados, con un Bulbasaur dentro). Paso a paso: 1) Lleva a Pikachu en el equipo, súbelo de nivel, gana combates de gimnasio con él y evita que se debilite para que su amistad suba. 2) Entra en la casa de Melanie en Ciudad Celeste y habla con ella. 3) Si Pikachu está lo bastante contento te ofrece el Bulbasaur: acepta y recibes Bulbasaur de nivel 10. 4) Si te dice que no, sigue entrenando con Pikachu y vuelve más tarde. Consejo: Bulbasaur evoluciona a Ivysaur (nv. 16) y Venusaur (nv. 32): son tres registros de golpe. Fuente: decompilación de pret (pokeyellow: scripts/CeruleanMelaniesHouse); WikiDex («Pokémon Amarillo»)."},{"key":"charmander-de-regalo-en-la-ruta-24","title":"Charmander de regalo en la Ruta 24","text":"Cuándo: tras cruzar el Puente Pepita, al norte de Ciudad Celeste. Dónde: Ruta 24, entrenador que está al final del camino, al norte del Puente Pepita. Paso a paso: 1) Sal de Ciudad Celeste hacia el norte y cruza el Puente Pepita venciendo a sus entrenadores y al recluta del Team Rocket del final. 2) Al norte del puente habla con el entrenador que quiere deshacerse de su Charmander. 3) Acepta: recibes Charmander de nivel 10 (si llevas seis Pokémon, va a la caja del PC). Consejo: Charmander evoluciona a Charmeleon (nv. 16) y Charizard (nv. 36). Fuente: decompilación de pret (pokeyellow: scripts/Route24); WikiDex («Ruta 24»)."},{"key":"intercambio-de-la-via-subterranea-cubone-por-machoke","title":"Intercambio de la Vía Subterránea: Cubone por Machoke","text":"Cuándo: cuando tengas un Cubone (Torre Pokémon, plantas 5 a 7, o Zona Safari). Dónde: Ruta 5, al sur de Ciudad Celeste: caseta de entrada de la Vía Subterránea. Paso a paso: 1) Captura un Cubone en la Torre Pokémon de Pueblo Lavanda (necesitas el Visor Silph para identificar fantasmas) o en la Zona Safari. 2) Vuelve a la caseta de la Vía Subterránea de la Ruta 5 y habla con la persona que busca un Cubone. 3) Acepta el intercambio: recibes un Machoke, que cuenta como capturado en la Pokédex. Consejo: el Machoke recibido no evoluciona por llegar de este intercambio: para Machamp hay que intercambiarlo con otra consola (bloque de evoluciones por intercambio). Fuente: decompilación de pret (pokeyellow: data/events/trades, scripts/UndergroundPathRoute5, data/wild/maps); WikiDex («Vía Subterránea»)."},{"key":"squirtle-de-regalo-en-ciudad-carmin","title":"Squirtle de regalo en Ciudad Carmín","text":"Cuándo: en cuanto tengas la Medalla Trueno del Teniente Surge. Dónde: Ciudad Carmín, la agente de policía que está en la calle. Paso a paso: 1) Gana la Medalla Trueno en el gimnasio de Ciudad Carmín. 2) Sal a la calle y habla con la agente de policía de la ciudad. 3) Acepta su Squirtle: recibes Squirtle de nivel 10. Consejo: si hablas con ella antes de la Medalla Trueno solo te pide que vuelvas; Squirtle evoluciona a Wartortle (nv. 16) y Blastoise (nv. 36). Fuente: decompilación de pret (pokeyellow: scripts/VermilionCity_2); WikiDex («Ciudad Carmín»)."},{"key":"intercambio-del-puesto-de-la-ruta-11-lickitung-por-dugtrio","title":"Intercambio del puesto de la Ruta 11: Lickitung por Dugtrio","text":"Cuándo: cuando tengas un Lickitung; en Amarillo solo sale salvaje en la Cueva Celeste (tras la Liga). Dónde: Ruta 11, al este de Ciudad Carmín: puesto de control, planta de arriba. Paso a paso: 1) Captura un Lickitung en la Cueva Celeste (planta baja del sótano) cuando se abra tras el Hall de la Fama. 2) Vuelve al puesto de la Ruta 11, sube a la planta de arriba y habla con quien busca un Lickitung. 3) Acepta: recibes un Dugtrio. Consejo: Dugtrio también se captura en la Cueva Diglett, así que este intercambio es opcional para la Pokédex. Fuente: decompilación de pret (pokeyellow: data/events/trades, scripts/Route11Gate2F, data/wild/maps); WikiDex («Ruta 11»)."},{"key":"ayudante-de-oak-de-la-ruta-11-buscaobjetos-30-especies","title":"Ayudante de Oak de la Ruta 11: Buscaobjetos (30 especies)","text":"Cuándo: cuando tengas 30 especies registradas como capturadas. Dónde: Ruta 11, puesto de control, planta de arriba. Paso a paso: 1) Comprueba en la Pokédex que tienes al menos 30 especies capturadas. 2) Sube a la planta de arriba del puesto de la Ruta 11 y habla con el ayudante del profesor Oak. 3) Te entrega el Buscaobjetos, que pita cuando hay un objeto oculto cerca. Consejo: si aún no llegas a 30, el ayudante te dice cuántas te faltan; vuelve más tarde. Fuente: decompilación de pret (pokeyellow: scripts/Route11Gate2F); WikiDex («Zahorí»)."},{"key":"intercambio-de-la-casa-de-la-ruta-2-clefairy-por-mr-mime","title":"Intercambio de la casa de la Ruta 2: Clefairy por Mr. Mime","text":"Cuándo: cuando tengas un Clefairy (Monte Moon) y acceso a la parte este de la Ruta 2. Dónde: Ruta 2, zona este: casa de intercambio (se llega cruzando la Cueva Diglett desde la Ruta 11 o usando Corte). Paso a paso: 1) Captura un Clefairy en el Monte Moon. 2) Cruza la Cueva Diglett desde la Ruta 11 (o corta el arbolito de la Ruta 2) y entra en la casa de intercambio. 3) Habla con quien busca un Clefairy y acepta: recibes a Mr. Mime, que no aparece salvaje. Consejo: captura otro Clefairy si también quieres registrar Clefable (Piedra Lunar). Fuente: decompilación de pret (pokeyellow: data/events/trades, scripts/Route2TradeHouse, data/maps/objects/Route2); WikiDex («Ruta 2»)."},{"key":"ayudante-de-oak-de-la-ruta-2-mo05-destello-10-especies","title":"Ayudante de Oak de la Ruta 2: MO05 Destello (10 especies)","text":"Cuándo: cuando tengas 10 especies registradas como capturadas. Dónde: Ruta 2, zona este: puesto de control que corta el camino, al sur de la casa de intercambio. Paso a paso: 1) Comprueba en la Pokédex que tienes al menos 10 especies capturadas. 2) Llega a la zona este de la Ruta 2 por la Cueva Diglett (desde la Ruta 11) o con Corte y entra en el puesto de control. 3) Habla con el ayudante del profesor Oak: te da la MO05 (Destello), que ilumina el Túnel Roca (requiere la Medalla Roca). Consejo: conviene recogerla antes de cruzar el Túnel Roca. Fuente: decompilación de pret (pokeyellow: scripts/Route2Gate, data/maps/objects/Route2); WikiDex («Ruta 2»)."},{"key":"ambar-viejo-aerodactyl","title":"Ámbar Viejo: Aerodactyl","text":"Cuándo: en cuanto puedas usar Corte fuera de combate (MO01 del capitán del S.S. Anne y Medalla Cascada); se revive en Isla Canela. Dónde: Ciudad Plateada, parte trasera del Museo de la Ciencia, y la sala de fósiles del Laboratorio Pokémon de Isla Canela. Paso a paso: 1) Vuelve a Ciudad Plateada y corta el arbolito que da paso a la entrada lateral del Museo de la Ciencia. 2) Entra por esa puerta: el científico de la sala te da el Ámbar Viejo. 3) En Isla Canela entrégalo al científico de la sala de fósiles del Laboratorio Pokémon (si está reviviendo tu otro fósil, recoge ese antes). 4) Sal a la calle, vuelve a entrar y recoge a Aerodactyl de nivel 30. Consejo: el Ámbar Viejo no caduca: puedes revivirlo cuando quieras. Fuente: decompilación de pret (pokeyellow: scripts/Museum1F, scripts/CinnabarLabFossilRoom); WikiDex («Ámbar Viejo», «Museo de la Ciencia de Ciudad Plateada»)."},{"key":"eevee-de-la-azotea-del-edificio-azulona","title":"Eevee de la azotea del Edificio Azulona","text":"Cuándo: al llegar a Ciudad Azulona. Dónde: Ciudad Azulona, Edificio Azulona (Mansión Azulona): casa de la azotea, a la que se sube por la puerta trasera. Paso a paso: 1) Rodea el Edificio Azulona y entra por la puerta trasera, en la cara norte. 2) Sube por las escaleras hasta la azotea y entra en la casita que hay arriba. 3) Coge la Poké Ball de la mesa: es Eevee de nivel 25. 4) Evoluciónalo con una de las piedras de la 4.ª planta del Centro Comercial Azulona: Piedra Agua (Vaporeon), Piedra Trueno (Jolteon) o Piedra Fuego (Flareon). Consejo: solo hay un Eevee por partida: elige bien la evolución; las otras dos tienen su bloque en «Completismo y colección». Fuente: decompilación de pret (pokeyellow: scripts/CeladonMansionRoofHouse, data/items/marts); WikiDex («Edificio Azulona»)."},{"key":"pokemon-de-premio-del-casino-rocket","title":"Pokémon de premio del Casino Rocket","text":"Cuándo: desde que llegas a Ciudad Azulona; las fichas se acumulan durante toda la partida. Dónde: Ciudad Azulona: restaurante (Monedero), Casino Rocket (fichas) y tienda de premios, junto al casino. Paso a paso: 1) Entra en el restaurante de Ciudad Azulona y habla con el hombre de la mesa de la esquina: te da el Monedero, sin el que no puedes tener fichas. 2) En el Casino Rocket compra fichas al dependiente (50 fichas por 1000 ₽) o gánalas en las tragaperras; busca también fichas sueltas por el suelo del casino. 3) Ve a la tienda de premios, el local de al lado del casino, y canjea los Pokémon: Abra (230 fichas, nv. 15), Vulpix (1000, nv. 18), Wigglytuff (2680, nv. 22), Scyther (6500, nv. 30), Pinsir (6500, nv. 30) y Porygon (9999, nv. 26). 4) En la misma tienda hay MT de premio: MT23 (Furia Dragón, 3300), MT15 (Hiperrayo, 5500) y MT50 (Sustituto, 7700). Consejo: Porygon no aparece en ningún otro sitio del juego; guarda antes de jugar a las tragaperras. Fuente: decompilación de pret (pokeyellow: data/events/prizes, data/events/prize_mon_levels, scripts/CeladonDiner, text/GameCorner); WikiDex («Casino Rocket», «Monedero»)."},{"key":"hitmonlee-o-hitmonchan-del-dojo-karate","title":"Hitmonlee o Hitmonchan del Dojo Karate","text":"Cuándo: al entrar en Ciudad Azafrán (antes o después del gimnasio de Sabrina). Dónde: Ciudad Azafrán, Dojo Karate: el edificio contiguo al gimnasio, también con cartel de gimnasio. Paso a paso: 1) Para entrar en Ciudad Azafrán, da una bebida (Agua Fresca, Refresco o Limonada, de las máquinas de la azotea del Centro Comercial Azulona) a uno de los guardias de las casetas. 2) En el Dojo Karate vence a los cuatro karatekas y al Maestro Karateka del fondo. 3) Coge una de las dos Poké Balls del fondo: Hitmonlee (izquierda) o Hitmonchan (derecha), ambos de nivel 30. Consejo: la otra Poké Ball ya no se puede coger: el Hitmon que dejes tiene su bloque en «Completismo y colección». Fuente: decompilación de pret (pokeyellow: data/maps/objects/FightingDojo, scripts/FightingDojo); WikiDex («Dojo Karate»)."},{"key":"lapras-de-silph-s-a","title":"Lapras de Silph S. A.","text":"Cuándo: durante la toma de Silph S. A. por el Team Rocket (también después). Dónde: Ciudad Azafrán, Silph S. A., 7.ª planta. Paso a paso: 1) Entra en Silph S. A. y sube hasta la 7.ª planta (usa los teletransportadores y la Llave Magnética de la 5.ª planta). 2) Habla con el empleado de Silph de esa planta. 3) Te regala un Lapras de nivel 15; si tienes el equipo lleno, va al PC. Consejo: es el único Lapras del juego. Fuente: decompilación de pret (pokeyellow: scripts/SilphCo7F); WikiDex («Silph S. A.»)."},{"key":"ayudante-de-oak-de-la-ruta-15-repartir-exp-50-especies","title":"Ayudante de Oak de la Ruta 15: Repartir Exp (50 especies)","text":"Cuándo: cuando tengas 50 especies registradas como capturadas. Dónde: Ruta 15, al este de Ciudad Fucsia: puesto de control, planta de arriba. Paso a paso: 1) Comprueba en la Pokédex que tienes al menos 50 especies capturadas. 2) Ve a la Ruta 15 (sal de Ciudad Fucsia por el este) y entra en el puesto de control. 3) Sube a la planta de arriba y habla con el ayudante del profesor Oak: te da el Repartir Exp. Consejo: en esta generación el Repartir Exp reparte la experiencia entre todo el equipo, aunque no combatan. Fuente: decompilación de pret (pokeyellow: scripts/Route15Gate2F); WikiDex («Ruta 15»)."},{"key":"intercambio-del-puesto-de-la-ruta-18-tangela-por-parasect","title":"Intercambio del puesto de la Ruta 18: Tangela por Parasect","text":"Cuándo: cuando tengas un Tangela (Zona Safari). Dónde: Ruta 18, al oeste de Ciudad Fucsia: puesto de control, planta de arriba. Paso a paso: 1) Captura un Tangela en la Zona Safari de Ciudad Fucsia (zonas centro y oeste). 2) Ve a la Ruta 18 y sube a la planta de arriba del puesto de control. 3) Habla con quien busca un Tangela y acepta: recibes un Parasect. Consejo: Parasect también sale por evolución de Paras (nv. 24). Fuente: decompilación de pret (pokeyellow: data/events/trades, scripts/Route18Gate2F, data/wild/maps); WikiDex («Ruta 18»)."},{"key":"intercambios-del-laboratorio-de-isla-canela-muk-rhydon-y-dew","title":"Intercambios del Laboratorio de Isla Canela: Muk, Rhydon y Dewgong","text":"Cuándo: al llegar a Isla Canela (Surf desde Pueblo Paleta por la Ruta 21 o desde Ciudad Fucsia por las Rutas 19-20). Dónde: Isla Canela, Laboratorio Pokémon: sala de fósiles (Muk) y sala de intercambios (Rhydon y Dewgong). Paso a paso: 1) Kangaskhan por Muk: captura un Kangaskhan en la Zona Safari (zona norte) y entrégalo en la sala de fósiles. 2) Golduck por Rhydon: consigue un Golduck (Ruta 6, o Psyduck al nivel 33) y entrégalo en la sala de intercambios. 3) Growlithe por Dewgong: captura un Growlithe en la Mansión Pokémon de Isla Canela y entrégalo en la sala de intercambios. Consejo: cada intercambio solo se hace una vez. Fuente: decompilación de pret (pokeyellow: data/events/trades, scripts/CinnabarLabFossilRoom, scripts/CinnabarLabTradeRoom, data/wild/maps); WikiDex («Isla Canela»)."}],"YELLOW-16":[{"key":"pokemon-que-no-aparecen-en-amarillo","title":"Pokémon que no aparecen en Amarillo","text":"Cuándo: en cualquier momento; conviene tras la Liga, con la Pokédex casi llena. Dónde: no están en Amarillo: se traen desde Rojo o Azul, en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy). Paso a paso: 1) Weedle, Kakuna y Beedrill; Ekans y Arbok; Raichu; Meowth y Persian; Koffing y Weezing; Jynx, Electabuzz y Magmar: 13 especies en total. 2) Pide a alguien con Rojo o Azul que los capture (o evolucione) y te los pase por cable; guarda antes, porque el intercambio guarda la partida. 3) Cada Pokémon recibido queda registrado como capturado en tu Pokédex. Consejo: con que los veas en combate no basta para el diploma: tienen que estar capturados. Con Pokekeep: abre la Librería, busca cada una de esas 13 especies y añádela legal a una caja de esta partida. Fuente: decompilación de pret (pokeyellow: data/wild (sin esas especies)); WikiDex («Pokémon Amarillo»)."},{"key":"el-fosil-que-no-elegiste","title":"El fósil que no elegiste","text":"Cuándo: en cualquier momento después del Monte Moon. Dónde: no se puede conseguir en esta partida: llega por intercambio, en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy). Paso a paso: 1) Si elegiste el Fósil Domo te faltan Omanyte y Omastar; si elegiste el Fósil Hélix, Kabuto y Kabutops. 2) Pide a alguien que haya revivido el otro fósil que te lo pase por cable. 3) Súbelo al nivel 40 para registrar su evolución. Consejo: Aerodactyl no entra aquí: sale del Ámbar Viejo, que sí está en todas las partidas. Con Pokekeep: abre la Librería, busca Kabuto u Omanyte (o su evolución) y añádelo a una caja de esta partida. Fuente: decompilación de pret (pokeyellow: data/maps/objects/MtMoonB2F); WikiDex («Monte Moon»)."},{"key":"el-hitmon-que-no-elegiste","title":"El Hitmon que no elegiste","text":"Cuándo: en cualquier momento después del Dojo Karate. Dónde: no se puede conseguir en esta partida: llega por intercambio, en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy). Paso a paso: 1) Si cogiste a Hitmonlee te falta Hitmonchan, y al revés. 2) Pide a alguien que haya elegido el otro que te lo pase por cable. 3) Al recibirlo queda registrado como capturado. Consejo: en esta generación no hay otra forma de conseguirlo en el juego. Con Pokekeep: abre la Librería, busca Hitmonlee o Hitmonchan y añade el que te falte a una caja de esta partida. Fuente: decompilación de pret (pokeyellow: scripts/FightingDojo); WikiDex («Dojo Karate»)."},{"key":"las-otras-dos-evoluciones-de-eevee","title":"Las otras dos evoluciones de Eevee","text":"Cuándo: en cualquier momento después de recoger a Eevee en el Edificio Azulona. Dónde: solo hay un Eevee por partida: las otras dos evoluciones (Vaporeon, Jolteon o Flareon) llegan por intercambio, en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy). Paso a paso: 1) Mira cuáles te faltan entre Vaporeon (Piedra Agua), Jolteon (Piedra Trueno) y Flareon (Piedra Fuego). 2) Pide a alguien que te pase un Eevee o esas evoluciones por cable. 3) Si recibes un Eevee, evoluciónalo con la piedra que corresponda (4.ª planta del Centro Comercial Azulona). Consejo: si pides Eevee sin evolucionar, registras el resto tú mismo con piedras. Con Pokekeep: abre la Librería, busca Vaporeon, Jolteon o Flareon y añade las que te falten a una caja de esta partida. Fuente: decompilación de pret (pokeyellow: scripts/CeladonMansionRoofHouse, data/items/marts); WikiDex («Eevee»)."},{"key":"evoluciones-por-intercambio-alakazam-machamp-golem-y-gengar","title":"Evoluciones por intercambio: Alakazam, Machamp, Golem y Gengar","text":"Cuándo: cuando tengas Kadabra, Machoke, Graveler y Haunter. Dónde: en cualquier Centro Pokémon, la recepcionista de la derecha del mostrador (conexión por Cable Game Link con otra Game Boy); necesitas una segunda consola y otra partida. Paso a paso: 1) Consigue Kadabra (Abra al nivel 16), Machoke (Machop al nivel 28, o el del intercambio de la Vía Subterránea), Graveler (Geodude al nivel 25) y Haunter (Gastly al nivel 25). 2) Guarda y envíalos por cable a otra partida: evolucionan al llegar a Alakazam, Machamp, Golem y Gengar. 3) Pide que te los devuelvan con otro intercambio: así quedan registrados como capturados en tu Pokédex. Consejo: un Pokémon recibido de los intercambios del juego no evoluciona al llegar; solo evoluciona cuando se intercambia por cable. Con Pokekeep: abre la Librería, busca Alakazam, Machamp, Golem o Gengar y añade los que te falten a una caja de esta partida. Fuente: decompilación de pret (pokeyellow: data/pokemon/evos_moves); WikiDex («Evolución por intercambio»)."},{"goal":"event-0"},{"goal":"battle0"},{"goal":"medal-type"}],"YELLOW-DETAIL1":[{"goal":"pokemon-145"},{"goal":"pokemon-144"},{"goal":"pokemon-146"},{"goal":"postgame"},{"goal":"pokemon-150"}]};
const api={byMission,get:id=>byMission[id]||null};if(typeof module==='object'&&module.exports)module.exports=api;else root.PokemonMissionBlocks=api;
})(typeof globalThis==='object'?globalThis:this);
